using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class GuideGestureReview {
 public static void Run(){
  CharacterRigImport.Run();EditorSceneManager.OpenScene("Assets/TabernacleRealistic.unity");TabernacleWorld.Instance=Object.FindFirstObjectByType<TabernacleWorld>();var eye=new GameObject("Gesture review eye").transform;eye.position=new Vector3(0,1.6f,3.2f);var guide=new GameObject("Gesture review robot").AddComponent<RobotGuide>();guide.Initialize(eye);guide.transform.position=Vector3.zero;guide.transform.rotation=Quaternion.identity;foreach(var t in guide.GetComponentsInChildren<Transform>())t.gameObject.layer=12;
  foreach(var r in guide.GetComponentsInChildren<Renderer>())if(r.name!="geometry_0")Debug.Log("FACE_BOUNDS "+r.name+" "+r.bounds+" local="+r.transform.localPosition);
  var camera=new GameObject("Gesture review camera").AddComponent<Camera>();camera.transform.position=new Vector3(.20f,1.02f,3.1f);camera.transform.LookAt(new Vector3(0,.9f,0));camera.fieldOfView=40;camera.cullingMask=1<<12;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.88f,.83f,.74f);camera.nearClipPlane=.1f;
  var light=new GameObject("Gesture review light").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(35,-25,0);light.intensity=1.2f;
  string folder="Documentation/Review-v0.6/Gestures";Directory.CreateDirectory(folder);var rig=guide.GetComponentInChildren<RiggedGuideVisual>();foreach(var name in new[]{"idle","think","explain","wave","point"}){guide.Thinking=name=="think";guide.Welcoming=name=="wave";guide.Speaking=name=="explain"||name=="point";guide.PlayGesture(name,12);for(int i=0;i<70;i++)rig.Evaluate(Time.unscaledTime+i/60f,1f/60);var bakedObjects=new System.Collections.Generic.List<GameObject>();foreach(var skin in guide.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh);var g=new GameObject("Baked gesture preview");g.layer=12;g.transform.SetPositionAndRotation(skin.transform.position,skin.transform.rotation);g.transform.localScale=Vector3.one;Debug.Log("GESTURE_BAKE "+name+" localBounds="+mesh.bounds+" scale="+skin.transform.lossyScale+" hand="+RiggedGuideVisual.Find(guide.transform,"RightHand").position);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;skin.enabled=false;bakedObjects.Add(g);}ExperienceReview.Capture(camera,folder+"/"+name+".png",800,1000);foreach(var g in bakedObjects){Object.DestroyImmediate(g.GetComponent<MeshFilter>().sharedMesh);Object.DestroyImmediate(g);}foreach(var skin in guide.GetComponentsInChildren<SkinnedMeshRenderer>())skin.enabled=true;}ConversationReview.Run();Debug.Log("GUIDE_GESTURE_VISUAL_REVIEW_CAPTURED");
 }
}
